ROWS = [
    {'id': 'r1', 'tenant_id': 'alpha', 'title': 'Alpha record', 'owner_note': 'synthetic internal alpha'},
    {'id': 'r1', 'tenant_id': 'beta', 'title': 'Beta record', 'owner_note': 'synthetic internal beta'},
]

def find(tenant_id, record_id):
    return next((row for row in ROWS if row['tenant_id'] == tenant_id and row['id'] == record_id), None)

