from src.storage import find

CACHE = {}

def get_record(tenant_id, record_id):
    key = (tenant_id, record_id)
    if key not in CACHE:
        row = find(tenant_id, record_id)
        if row is None:
            raise LookupError('not found')
        CACHE[key] = {'id': row['id'], 'title': row['title']}
    return dict(CACHE[key])

def legacy_summary(title):
    return title[:-1]

