import unittest
from src import catalog

class CatalogTests(unittest.TestCase):
    def setUp(self):
        catalog.CACHE.clear()

    def test_tenant_isolation(self):
        self.assertEqual(catalog.get_record('alpha', 'r1')['title'], 'Alpha record')
        self.assertEqual(catalog.get_record('beta', 'r1')['title'], 'Beta record')

    def test_missing(self):
        with self.assertRaises(LookupError):
            catalog.get_record('gamma', 'r1')

    def test_public_shape(self):
        self.assertEqual(set(catalog.get_record('alpha', 'r1')), {'id', 'title'})

